type SearchWeightsBase = {
  /** Weight for fuzzy search results @default 0.45 */
  fuzzy: number
  /** Weight for prefix search results @default 0.375 */
  prefix: number
}

weights?: Partial<SearchWeightsBase>

function validateWeights(weights?: Partial<SearchWeights>): void {
  if (!weights) return;

  if (weights.fuzzy !== undefined && (weights.fuzzy < 0 || weights.fuzzy > 1)) {
    throw new RangeError(`SearchOptions.weights.fuzzy must be between 0 and 1, got ${weights.fuzzy}`);
  }

  if (weights.prefix !== undefined && (weights.prefix < 0 || weights.prefix > 1)) {
    throw new RangeError(`SearchOptions.weights.prefix must be between 0 and 1, got ${weights.prefix}`);
  }
}

